def curated():
 rows=[]
 for i,(topic,en,ar) in enumerate(DIALOGUES):
  split='dev' if i%8==6 else 'test' if i%8==7 else 'train'
  for language,dialogue in [('English',en),('Arabic',ar)]:
   m=[{'role':'system','content':SYSTEM}]
   for j in (0,2):
    m+=pair(dialogue[j],dialogue[j+1],language)
    rows.append({'id':f'curated-{topic}-{language}-{j}','group_id':f'curated-{topic}','source':'project-authored-synthetic',
       'language':language,'split':split,'messages':list(m)})
 return rows
